import subprocess,os,sys,json,hashlib,datetime,pathlib
base=pathlib.Path(__file__).resolve().parent; root=pathlib.Path((base/'output-root.txt').read_text().strip()); name=sys.argv[1]; cwd=sys.argv[2]; cmd=sys.argv[3:]; env=os.environ.copy(); env['PATH']=str(pathlib.Path.home()/'.nvm/versions/node/v24.22.2/bin')+':'+env['PATH'];env['PYTHONDONTWRITEBYTECODE']='1';env['PYTEST_ADDOPTS']='-p no:cacheprovider'
def hashes():
 paths=set(subprocess.check_output(['git','diff','--name-only'],cwd=cwd,text=True).splitlines()+subprocess.check_output(['git','ls-files','--others','--exclude-standard'],cwd=cwd,text=True).splitlines());return {p:{'bytes':(pathlib.Path(cwd)/p).stat().st_size,'sha256':hashlib.sha256((pathlib.Path(cwd)/p).read_bytes()).hexdigest()} for p in sorted(paths) if (pathlib.Path(cwd)/p).is_file()}
beforeHashes=hashes()
log=root/(name+'.log'); receipt=root/(name+'.json'); start=datetime.datetime.now().isoformat(); before=subprocess.check_output(['git','status','--porcelain'],cwd=cwd,text=True);head=subprocess.check_output(['git','rev-parse','HEAD'],cwd=cwd,text=True).strip()
with log.open('w') as f:p=subprocess.run(cmd,cwd=cwd,env=env,stdout=f,stderr=subprocess.STDOUT)
r={'argv':cmd,'cwd':cwd,'environment':{'PATH_prefix':str(pathlib.Path.home()/'.nvm/versions/node/v24.22.2/bin'),'PYTHONDONTWRITEBYTECODE':'1','PYTEST_ADDOPTS':'-p no:cacheprovider'},'start':start,'end':datetime.datetime.now().isoformat(),'exit':p.returncode,'head':head,'beforeFileHashes':beforeHashes,'afterFileHashes':hashes(),'beforeStatus':before,'afterStatus':subprocess.check_output(['git','status','--porcelain'],cwd=cwd,text=True),'log':str(log),'bytes':log.stat().st_size,'sha256':hashlib.sha256(log.read_bytes()).hexdigest()};receipt.write_text(json.dumps(r,indent=2)+'\n')
with (base.parent/'task-final-correction-report.md').open('a') as f:f.write('\nCheck `'+name+'`: own exit '+str(p.returncode)+'; complete receipt `'+str(receipt)+'`; log `'+str(log)+'`, '+str(r['bytes'])+' bytes, SHA256 `'+r['sha256']+'`.\n')
print(json.dumps({'receipt':str(receipt),'exit':p.returncode,'log':str(log),'bytes':r['bytes'],'sha256':r['sha256']}));print(log.read_text()[-6000:]);sys.exit(p.returncode)
